selected = sys.argv[1:]
assert selected and all(k in specs for k in selected), selected
meta_path = w / 'notes/register_metadata.json'
meta = json.loads(meta_path.read_text())
paper_path = w / 'SECTIONS_OVER_Q_paper.tex'
paper = paper_path.read_text()
report_path = w / 'SECTIONS_OVER_Q_report.md'
lines = report_path.read_text().splitlines()
assert lines[0] == 'INCOMPLETE'
for key in selected:
    spec = specs[key]
    source = w / 'sections' / spec['file']
    assert source.exists() and ('{'+key+'}{Proved}') in source.read_text()
    record = {k: spec[k] for k in ['answers', 'depends_on', 'notes']}
    record.update({
      'uses_local_theorem': 'no; locally matching quotient sections are the explicitly stated domain' if key in ['A.171','A.172'] else 'no',
      'manuscript_passages': 'cote149; scans54–58 and126–127; exact full-quotient and norm comparison maps'
    })
    meta[key] = record
    answers = {a.strip() for a in spec['answers'].split(';')}
    for i, line in enumerate(lines[:55]):
        if not line.startswith('| '): continue
        cells = [x.strip() for x in line.strip().strip('|').split('|')]
        if len(cells) == 3 and cells[0] in answers:
            if key not in cells[1]: cells[1] += ', ' + key
            if spec['detail'] not in cells[2]: cells[2] += ' ' + spec['detail']
            lines[i] = '| ' + ' | '.join(cells) + ' |'
    heading = '## Continued work: ' + spec['heading']
    if heading not in lines:
        lines += ['', heading, '', stamp + ': ' + spec['detail'], '', spec['notes'], '']
    audit = stamp + ' ' + key + ' integrated after complete source audit and exact map checks. ' + spec['detail'] + '\n'
    for name in ['notes/hour13_root_audits.md', 'notes/root_progress.md']:
        with (w / name).open('a') as f: f.write('\n' + audit)

# Keep numerical order even when a later independent proof was audited first.
for key, spec in specs.items():
    paper = paper.replace('\\input{sections/' + spec['file'] + '}\n', '')
anchor = '\\input{sections/two_inert_genus_character.tex}'
assert paper.count(anchor)==1
active = [key for key in specs if key in meta]
active.sort(key=lambda x: int(x.split('.')[1]))
addition = ''.join('\n\\input{sections/' + specs[key]['file'] + '}' for key in active)
paper = paper.replace(anchor, anchor + addition, 1)
paper_path.write_text(paper)
meta_path.write_text(json.dumps(meta, indent=2, ensure_ascii=False)+'\n')
report_path.write_text('\n'.join(lines)+'\n')
proc = subprocess.run(['python', str(w/'code/build_register.py')], capture_output=True, text=True, check=True)
out = 'Integrated audited sections: '+', '.join(selected)+'\n'+proc.stdout
suffix = '_'.join(x.replace('.','') for x in selected)
Path(__file__).with_name('integrate_hour13_'+suffix+'_output.txt').write_text(out)
print(out, end='')
